import{_ as s,o as t,c as e,a5 as i}from"./chunks/framework.BjM_ivYE.js";const k=JSON.parse('{"title":"PTZ Camera API","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/ptz-camera-api.md","filePath":"software/ptz-camera-api.md","lastUpdated":1789720001000}'),n={name:"software/ptz-camera-api.md"};function o(r,a,l,h,p,d){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="ptz-camera-api" tabindex="-1">PTZ Camera API <a class="header-anchor" href="#ptz-camera-api" aria-label="Permalink to &quot;PTZ Camera API&quot;">​</a></h1><p>The PTZ camera is a standalone <a href="https://www.hanwhavision.com/ko/products/product-details/XNZ-L6320AG" target="_blank" rel="noreferrer">Hanwha Vision XNZ-L6320AG</a> and is controlled <strong>directly</strong>, without going through the robot&#39;s software. It sits on the robot&#39;s internal network (default <code>192.168.0.100</code>) and supports three standard interfaces:</p><ul><li><strong>RTSP</strong> — live H.264 / H.265 video</li><li><strong>SUNAPI</strong> — Hanwha&#39;s HTTP CGI API for pan / tilt / zoom, presets, focus, and audio</li><li><strong>ONVIF</strong> — Profile S / T for third-party VMS and tools</li></ul><p>For the camera&#39;s mechanical and optical specifications, see <a href="/RBQ/manual/related-products/ptz-camera.html">PTZ Camera</a>.</p><h2 id="control-paths" tabindex="-1">Control paths <a class="header-anchor" href="#control-paths" aria-label="Permalink to &quot;Control paths {#control-paths}&quot;">​</a></h2><p>There are two ways to drive the PTZ camera from code.</p><table tabindex="0"><thead><tr><th></th><th>Directly to the camera (this page)</th><th>Through the robot (ROS2 / DDS)</th></tr></thead><tbody><tr><td>Interfaces</td><td>SUNAPI (HTTPS CGI) · RTSP · ONVIF Profile S / T</td><td><code>/rbq/cmd/ptz</code> · <code>/rbq/ptz</code> (<code>std_msgs/Float64MultiArray</code>)</td></tr><tr><td>Endpoint</td><td>The camera at <code>192.168.0.100</code></td><td>The robot&#39;s DDS domain</td></tr><tr><td>Pan / tilt / zoom</td><td>Absolute and continuous moves, presets, focus</td><td>Absolute pan / tilt / zoom setpoint — <strong>all three applied together</strong></td></tr><tr><td>Video</td><td>Camera RTSP, H.264 / H.265, profile-selectable</td><td>Robot Streamer RTSP — see <a href="/RBQ/software/media.html">Media</a></td></tr><tr><td>Audio</td><td>Speaker and microphone (SUNAPI audio, RTSP back-channel)</td><td>Not available</td></tr><tr><td>Third-party VMS</td><td>ONVIF</td><td>Not available</td></tr><tr><td>Requires</td><td>A camera account and access to the robot&#39;s internal network</td><td>The <code>Ptz</code> app running on the robot</td></tr></tbody></table><p>Use the <a href="/RBQ/software/sdk/ros/topics.html#vision-ptz-camera">ROS2 topics</a> when the camera moves as part of robot SDK code. Use direct control when you need the camera&#39;s own features — presets, focus, audio, or ONVIF.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-caution-i" aria-hidden="true">!</span></div><div class="sb-content"><p class="custom-block-title">Credentials</p><p>The camera uses HTTP <strong>Digest</strong> authentication (the SUNAPI default). The <code>--anyauth</code> flag in the examples lets <code>curl</code> negotiate it automatically — a plain <code>-u</code> sends Basic only and is rejected with <strong>401</strong>. Use the account provided with your robot and replace <code>&lt;user&gt;</code> / <code>&lt;password&gt;</code>. Keep the camera on a trusted network.</p></div></div><h2 id="live-video-rtsp" tabindex="-1">Live Video (RTSP) <a class="header-anchor" href="#live-video-rtsp" aria-label="Permalink to &quot;Live Video (RTSP) {#live-video-rtsp}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffplay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rtsp://&lt;user&gt;:&lt;password&gt;@192.168.0.100:554/profile2/media.smp&quot;</span></span></code></pre></div><p>The profile number selects the stream (resolution / codec); the camera lists its profiles in its own web UI.</p><h2 id="pan-tilt-zoom-sunapi" tabindex="-1">Pan / Tilt / Zoom (SUNAPI) <a class="header-anchor" href="#pan-tilt-zoom-sunapi" aria-label="Permalink to &quot;Pan / Tilt / Zoom (SUNAPI) {#pan-tilt-zoom-sunapi}&quot;">​</a></h2><p>SUNAPI is served over HTTPS. The camera ships with a self-signed certificate, so <code>-k</code> (skip verification) is used below. Common calls:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Read the current zoom level</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --anyauth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://192.168.0.100/stw-cgi/ptzcontrol.cgi?msubmenu=query&amp;action=view&amp;Channel=0&amp;Query=Zoom&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Absolute zoom to 8x  (range 1-32)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --anyauth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://192.168.0.100/stw-cgi/ptzcontrol.cgi?msubmenu=absolute&amp;action=control&amp;Zoom=8&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Continuous zoom: in / stop / out  -&gt;  1 / 0 / -1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --anyauth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passwor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://192.168.0.100/stw-cgi/ptzcontrol.cgi?msubmenu=continuous&amp;action=control&amp;Zoom=1&quot;</span></span></code></pre></div><p>Pan, tilt, and presets use the same <code>ptzcontrol.cgi</code> endpoint with <code>Pan</code> / <code>Tilt</code> parameters and <code>msubmenu=preset</code>. For the complete command set — pan/tilt ranges, presets, focus, audio in/out, event, and image settings — see the <strong>Hanwha SUNAPI</strong> reference for the XNZ-L6320AG.</p><h2 id="speaker-microphone" tabindex="-1">Speaker &amp; Microphone <a class="header-anchor" href="#speaker-microphone" aria-label="Permalink to &quot;Speaker &amp; Microphone {#speaker-microphone}&quot;">​</a></h2><p>The 25 W speaker and the microphone are the camera&#39;s own two-way audio, available over SUNAPI audio and the RTSP back-channel. See the Hanwha SUNAPI reference for audio in/out.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>These interfaces talk to the camera directly. The robot&#39;s own software also reads the camera to build its composite views, but that path is internal — integrations use the standard interfaces above or the ROS2 PTZ topics.</p></div></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also {#see-also}&quot;">​</a></h2><ul><li><a href="/RBQ/manual/related-products/ptz-camera.html">PTZ Camera</a> — mechanical, optical, and thermal specifications</li><li><a href="/RBQ/manual/gui/ptz.html">PTZ camera</a> — operating the camera from the app</li><li><a href="/RBQ/software/sdk/ros/topics.html#vision-ptz-camera">Topic Reference — Vision — PTZ Camera</a> — robot-mediated pan / tilt / zoom over ROS2</li><li><a href="/RBQ/software/media.html">Media</a> — RTSP streams published by the robot itself</li></ul>`,21)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
